import React from 'react';
import { motion, Variants } from 'framer-motion';

interface AnimatedTextProps {
  text: string;
  className?: string;
  element?: 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div';
  preserveWhitespace?: boolean;
  onAnimationComplete?: () => void;
}

/**
 * AnimatedText - A component that renders text with a character-by-character animation
 * in a strict sequential order (left to right).
 */
const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  className = '',
  element = 'p',
  preserveWhitespace = false,
  onAnimationComplete
}) => {
  // Split text into individual characters
  const characters = Array.from(text);

  // Harder delay between characters for more visibility
  const staggerDelay = 0.035;

  // Animation container variant with explicit staggering
  const container: Variants = {
    hidden: { opacity: 1 },
    visible: { 
      opacity: 1,
      transition: {
        staggerChildren: staggerDelay,
        delayChildren: 0,
        staggerDirection: 1,
        when: "beforeChildren"
      }
    }
  };

  // Character animation variant - more visible transition
  const child: Variants = {
    hidden: { 
      opacity: 0,
      display: 'inline-block'
    },
    visible: {
      opacity: 1,
      display: 'inline-block',
      transition: { 
        duration: 0.03,
        ease: "easeIn"
      }
    }
  };

  // Create the characters as motion.span elements
  const animatedCharacters = characters.map((char, index) => (
    <motion.span
      key={`${index}-${char}`}
      variants={child}
      // Add custom transition delay to ensure sequential appearance
      transition={{
        delay: index * staggerDelay
      }}
    >
      {char === ' ' ? '\u00A0' : char}
    </motion.span>
  ));

  // Calculate when animation should be considered complete
  // This ensures all characters are shown before signaling completion
  const handleAnimationComplete = () => {
    // Using a timeout to ensure all character animations are truly complete
    setTimeout(() => {
      if (onAnimationComplete) {
        onAnimationComplete();
      }
    }, staggerDelay * 1000); // Convert to milliseconds
  };

  // Render the appropriate element with the animated characters
  const commonProps = {
    className: `animated-text ${className}`,
    style: { whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const },
    onAnimationComplete: handleAnimationComplete,
    variants: container,
    initial: "hidden",
    animate: "visible"
  };

  switch (element) {
    case 'h1':
      return <motion.h1 {...commonProps}>{animatedCharacters}</motion.h1>;
    case 'h2':
      return <motion.h2 {...commonProps}>{animatedCharacters}</motion.h2>;
    case 'h3':
      return <motion.h3 {...commonProps}>{animatedCharacters}</motion.h3>;
    case 'h4':
      return <motion.h4 {...commonProps}>{animatedCharacters}</motion.h4>;
    case 'span':
      return <motion.span {...commonProps}>{animatedCharacters}</motion.span>;
    case 'div':
      return <motion.div {...commonProps}>{animatedCharacters}</motion.div>;
    case 'p':
    default:
      return <motion.p {...commonProps}>{animatedCharacters}</motion.p>;
  }
};

export default AnimatedText;
